import { Carrera } from './carrera.model';
import { Materia } from './materia.model';
import { RegistroAcademico } from './registro-academico.model';

export class Alumno {
  private legajo: string;
  private nombre: string;
  private promedio: number;
  private carrera: Carrera;
  private registros: RegistroAcademico[];

  constructor(
    legajo: string,
    nombre: string,
    promedio: number,
    carrera: Carrera,
    registros: RegistroAcademico[],
  ) {
    this.legajo = legajo;
    this.nombre = nombre;
    this.promedio = promedio;
    this.carrera = carrera;
    this.registros = registros;
  }

  getLegajo(): string { return this.legajo; }
  getNombre(): string { return this.nombre; }
  getPromedio(): number { return this.promedio; }
  getCarrera(): Carrera { return this.carrera; }
  getRegistros(): RegistroAcademico[] { return this.registros; }

  getMateriasAprobadas(): Materia[] {
    return this.registros
      .filter(r => r.estaAprobada())
      .map(r => r.getMateria());
  }

  getMateriasDisponibles(): Materia[] {
    const aprobadas = this.getMateriasAprobadas();
    return this.carrera.getPlanEstudio().getMaterias()
      .filter(m => !aprobadas.find(a => a.getCodigo() === m.getCodigo()))
      .filter(m => m.estaDisponible(aprobadas));
  }

  getPorcentajeAvance(): number {
    const total = this.carrera.getTotalMaterias();
    if (total === 0) return 0;
    return Math.round((this.getCantidadAprobadas() / total) * 100);
  }

  getCantidadAprobadas(): number {
    return this.getMateriasAprobadas().length;
  }
}
